create schema TypeOne (id long, mylong long, mystring long);
@public create window MyInfraTwo#unique(id) as select * from TypeOne;
on TypeOne as t1 merge MyInfraTwo nm where nm.id = t1.id
  when not matched and mystring = 0 then insert select *
  when not matched then insert (id, mylong, mystring) select 0L, 0L, 0L

